INSERT INTO materials (name, category, price, unit, description, image_url, in_stock, sort_order, archived) VALUES ('Кирпич силикатный коричневый пустотелый полуторный М-150', 'kirpich', '27,20 ₽', 'шт', 'Борский силикатный завод. Размер 250×120×88 мм. В упаковке (на поддоне) 336 шт — 9 139,20 ₽. Вес поддона 1340 кг. Коричневый пустотелый — для красивой кладки, лёгкий и тёплый.', '/img/brick-brown-card.jpg', true, 5, false);